 const save=(n:Notebook)=>{const previous=notebookRef.current.find(x=>x.id===n.id),priorProgress=progressRef.current[n.id];if(previous&&priorProgress){const reconciled=reconcileNotebookProgress(previous,n,priorProgress);if(reconciled!==priorProgress)void savePlay(reconciled);}notebookRef.current=[n,...notebookRef.current.filter(x=>x.id!==n.id)];setNotebooks(notebookRef.current);return queueSave(`notebook:${n.id}`,()=>saveNotebook(n));};
