  if(!s&&!chapter&&campaignActivities.length){const next=nextCampaignActivity(campaign,progress!)||campaignActivities[0].id;playActivity(next);return;}
  if(!s&&!chapter&&!selected.cards.length&&campaign.chapters.length){study(campaign.chapters.find(c=>!progress?.studies?.[c.id]?.completed)||campaign.chapters[0]);return;}
